package com.locationinfo;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class LocationInfoPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(LocationInfoPlugin.class);
		RuneLite.main(args);
	}
}

package com.locationinfo;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup(LocationInfoConfig.GROUP)
public interface LocationInfoConfig extends Config
{
	// Keep the group stable: it is the namespace RuneLite uses for saved settings.
	String GROUP = "location-info";
	// The explicit key is also used by the one-time legacy preference migration.
	String CAMERA_ZOOM_KEY = "cameraZoom";
	// This differs from the old cameraZ key, which previous versions used for
	// the zoom preference and which is migrated during plugin startup.
	String CAMERA_POSITION_Z_KEY = "cameraPositionZ";
	String PLAYER_COORDINATES_SECTION = "playerCoordinates";
	String CAMERA_INFO_SECTION = "cameraInfo";
	String DEBUGGING_SECTION = "debugging";

	@ConfigSection(
		name = "Player coordinates",
		description = "Player world-coordinate display settings",
		position = 2,
		closedByDefault = true
	)
	String playerCoordinatesSection = PLAYER_COORDINATES_SECTION;

	@ConfigSection(
		name = "Camera info",
		description = "Camera display settings",
		position = 6,
		closedByDefault = true
	)
	String cameraInfoSection = CAMERA_INFO_SECTION;

	@ConfigSection(
		name = "Debugging",
		description = "Game-state diagnostics for learning and plugin development",
		position = 10,
		closedByDefault = true
	)
	String debuggingSection = DEBUGGING_SECTION;

	// Each default method represents one setting in RuneLite's plugin panel.
	@ConfigItem(keyName = "addAll", name = "Add all", position = 0,
		description = "Show every value, regardless of its individual setting")
	default boolean addAll()
	{
		return false;
	}

	@ConfigItem(keyName = "names", name = "Names", position = 1,
		description = "Show labels next to coordinate values")
	default boolean names()
	{
		return true;
	}

	@ConfigItem(keyName = "playerX", name = "Player X", position = 3, section = PLAYER_COORDINATES_SECTION,
		description = "Show the player's world X coordinate")
	default boolean playerX()
	{
		return true;
	}

	@ConfigItem(keyName = "playerY", name = "Player Y", position = 4, section = PLAYER_COORDINATES_SECTION,
		description = "Show the player's world Y coordinate")
	default boolean playerY()
	{
		return true;
	}

	@ConfigItem(keyName = "playerZ", name = "Player Z", position = 5, section = PLAYER_COORDINATES_SECTION,
		description = "Show the player's world plane (Z coordinate)")
	default boolean playerZ()
	{
		return true;
	}

	@ConfigItem(keyName = "cameraX", name = "Camera X", position = 11, section = DEBUGGING_SECTION,
		description = "Show the camera X position")
	default boolean cameraX()
	{
		return true;
	}

	@ConfigItem(keyName = "cameraY", name = "Camera Y", position = 12, section = DEBUGGING_SECTION,
		description = "Show the camera Y position")
	default boolean cameraY()
	{
		return true;
	}

	@ConfigItem(keyName = CAMERA_POSITION_Z_KEY, name = "Camera Z", position = 13, section = DEBUGGING_SECTION,
		description = "Show the camera Z position")
	default boolean cameraZ()
	{
		return true;
	}

	@ConfigItem(keyName = CAMERA_ZOOM_KEY, name = "Camera zoom", position = 7, section = CAMERA_INFO_SECTION,
		description = "Show the current camera zoom value")
	default boolean cameraZoom()
	{
		return true;
	}

	@ConfigItem(keyName = "cameraYaw", name = "Camera yaw", position = 14, section = DEBUGGING_SECTION,
		description = "Show the raw camera yaw value")
	default boolean cameraYaw()
	{
		return true;
	}

	@ConfigItem(keyName = "cameraYawDegrees", name = "Horizontal rotation", position = 8, section = CAMERA_INFO_SECTION,
		description = "Show the camera's yaw rotation in degrees")
	default boolean cameraYawDegrees()
	{
		return true;
	}

	@ConfigItem(keyName = "cameraPitch", name = "Camera pitch", position = 15, section = DEBUGGING_SECTION,
		description = "Show the raw camera pitch value")
	default boolean cameraPitch()
	{
		return true;
	}

	@ConfigItem(keyName = "cameraPitchDegrees", name = "Vertical rotation", position = 9, section = CAMERA_INFO_SECTION,
		description = "Show the camera's pitch rotation in degrees")
	default boolean cameraPitchDegrees()
	{
		return true;
	}

	@ConfigItem(keyName = "sceneBaseX", name = "Scene base X", position = 16, section = DEBUGGING_SECTION,
		description = "Show the scene origin world X tile; -1 in unsupported scenes")
	default boolean sceneBaseX()
	{
		return true;
	}

	@ConfigItem(keyName = "sceneBaseY", name = "Scene base Y", position = 17, section = DEBUGGING_SECTION,
		description = "Show the scene origin world Y tile; -1 in unsupported scenes")
	default boolean sceneBaseY()
	{
		return true;
	}

	@ConfigItem(keyName = "clickPrediction", name = "Click prediction", position = 18, section = DEBUGGING_SECTION,
		description = "Show whether the current default click is an action")
	default boolean clickPrediction()
	{
		return true;
	}

	@ConfigItem(keyName = "hoveredEntityId", name = "Hovered object/NPC ID", position = 19, section = DEBUGGING_SECTION,
		description = "Show the ID of the object or NPC under the mouse")
	default boolean hoveredEntityId()
	{
		return true;
	}

	@ConfigItem(keyName = "lastClickStatus", name = "Last click status", position = 20, section = DEBUGGING_SECTION,
		description = "Show whether the last click was an action")
	default boolean lastClickStatus()
	{
		return true;
	}

	@ConfigItem(keyName = "currentModalInterface", name = "Modal UI", position = 21,
		section = DEBUGGING_SECTION,
		description = "Show the currently open modal-interface parent group ID; 0 means none")
	default boolean currentModalInterface()
	{
		return true;
	}
}

package com.locationinfo;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.WorldView;
import net.runelite.api.MenuAction;
import net.runelite.api.MenuEntry;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;

/**
 * Renders the selected player and camera information in the top-left corner.
 * The overlay is redrawn by RuneLite, so it reads the current client state at
 * render time instead of maintaining its own copy of location or camera data.
 */
public class LocationInfoOverlay extends OverlayPanel
{
	// RuneLite represents a full yaw rotation using 16,384 angular units.
	private static final int FULL_TURN_UNITS = 16_384;
	// These client pitch limits map the permitted vertical camera range to 0-90 degrees.
	private static final int MIN_CAMERA_PITCH = 164;
	private static final int MAX_CAMERA_PITCH = 4_160;
	// A monospaced, high-contrast font keeps the displayed values easy to read.
	private static final Font DISPLAY_FONT = new Font(Font.MONOSPACED, Font.PLAIN, 24);
	// Padding and spacing define the tightly sized, individual text backgrounds.
	private static final int LINE_PADDING_X = 3;
	private static final int LINE_PADDING_Y = 2;
	private static final int WORD_GAP = 2;
	private static final int CLICK_STATUS_SIZE = 20;

	private final Client client;
	private final LocationInfoConfig config;
	// Updated by the plugin event handler and retained until the next click occurs.
	private boolean lastClickWasRed;
	// Current modal parent group only; zero means no modal interface is open.
	private int currentModalInterfaceId;

	@Inject
	private LocationInfoOverlay(Client client, LocationInfoConfig config)
	{
		this.client = client;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		// OverlayPanel keeps child components between frames, so rebuild the list
		// from the current settings and client data each time it is rendered.
		panelComponent.getChildren().clear();
		// Individual line components paint their own small white backgrounds.
		panelComponent.setBackgroundColor(null);
		panelComponent.setBorder(new Rectangle());
		panelComponent.setGap(new Point(0, 2));
		Player player = client.getLocalPlayer();
		if (player == null || client.getGameState() != GameState.LOGGED_IN)
		{
			// There is no world location to show before a local player exists.
			return null;
		}

		WorldPoint location = player.getWorldLocation();
		if (config.addAll() || config.playerX())
		{
			addLine("Player X", location.getX());
		}
		if (config.addAll() || config.playerY())
		{
			addLine("Player Y", location.getY());
		}
		if (config.addAll() || config.playerZ())
		{
			addLine("Player Z", location.getPlane());
		}
		if (config.addAll() || config.cameraX())
		{
			addLine("Camera X", client.getCameraX());
		}
		if (config.addAll() || config.cameraY())
		{
			addLine("Camera Y", client.getCameraY());
		}
		if (config.addAll() || config.cameraZ())
		{
			addLine("Camera Z", client.getCameraZ());
		}
		if (config.addAll() || config.cameraZoom())
		{
			addLine("Camera zoom", client.getScale());
		}
		if (config.addAll() || config.cameraYaw())
		{
			addLine("Camera yaw", client.getCameraYaw());
		}
		if (config.addAll() || config.cameraYawDegrees())
		{
			addLine("Horizontal rotation", toYawDegrees(client.getCameraYaw()), " deg");
		}
		if (config.addAll() || config.cameraPitch())
		{
			addLine("Camera pitch", client.getCameraPitch());
		}
		if (config.addAll() || config.cameraPitchDegrees())
		{
			addLine("Vertical rotation", toPitchDegrees(client.getCameraPitch()), " deg");
		}
		WorldView worldView = client.getTopLevelWorldView();
		boolean supportedScene = worldView != null && !worldView.isInstance()
			&& player.getWorldView() == worldView;
		if (config.addAll() || config.sceneBaseX())
		{
			addLine("Scene base X", supportedScene ? worldView.getBaseX() : -1);
		}
		if (config.addAll() || config.sceneBaseY())
		{
			addLine("Scene base Y", supportedScene ? worldView.getBaseY() : -1);
		}
		if (config.clickPrediction())
		{
			// Red means the current default click is an interaction; yellow means it
			// is a walk, cancel, unknown action, or an open context menu.
			panelComponent.getChildren().add(new ClickStatusComponent(isActionHover()));
		}
		if (config.addAll() || config.hoveredEntityId())
		{
			addLine("Hovered ID", getHoveredEntityId());
		}
		if (config.lastClickStatus())
		{
			panelComponent.getChildren().add(new ClickStatusComponent(lastClickWasRed));
		}
		if (config.addAll() || config.currentModalInterface())
		{
			addLine("Modal UI", currentModalInterfaceId);
		}

		return super.render(graphics);
	}

	private int getHoveredEntityId()
	{
		if (client.isMenuOpen())
		{
			return -1;
		}

		MenuEntry[] entries = client.getMenu().getMenuEntries();
		for (int i = entries.length - 1; i >= 0; i--)
		{
			MenuEntry entry = entries[i];
			switch (entry.getType())
			{
				case NPC_FIRST_OPTION:
				case NPC_SECOND_OPTION:
				case NPC_THIRD_OPTION:
				case NPC_FOURTH_OPTION:
				case NPC_FIFTH_OPTION:
				case WIDGET_TARGET_ON_NPC:
				case ITEM_USE_ON_NPC:
				case EXAMINE_NPC:
					NPC npc = entry.getNpc();
					if (npc != null)
					{
						return npc.getId();
					}
					break;
				case GAME_OBJECT_FIRST_OPTION:
				case GAME_OBJECT_SECOND_OPTION:
				case GAME_OBJECT_THIRD_OPTION:
				case GAME_OBJECT_FOURTH_OPTION:
				case GAME_OBJECT_FIFTH_OPTION:
				case WIDGET_TARGET_ON_GAME_OBJECT:
				case ITEM_USE_ON_GAME_OBJECT:
				case EXAMINE_OBJECT:
					return entry.getIdentifier();
				default:
					break;
			}
		}
		return -1;
	}

	private boolean isActionHover()
	{
		// A context menu has no single default action under the cursor.
		if (client.isMenuOpen())
		{
			return false;
		}

		MenuEntry[] entries = client.getMenu().getMenuEntries();
		if (entries.length == 0)
		{
			return false;
		}

		// RuneLite stores the default left-click entry at the end of this array.
		MenuEntry defaultEntry = entries[entries.length - 1];
		return isRedClick(defaultEntry.getType());
	}

	void setLastClickWasRed(MenuAction action)
	{
		// Save the result separately from hover state, which can change each frame.
		lastClickWasRed = isRedClick(action);
	}

	void setCurrentModalInterfaceId(int groupId)
	{
		currentModalInterfaceId = groupId;
	}

	private static boolean isRedClick(MenuAction action)
	{
		// Walking and cancelling are non-interaction outcomes. Every other menu
		// action is displayed as an interaction using the red status color.
		return action != MenuAction.WALK && action != MenuAction.CANCEL && action != MenuAction.UNKNOWN;
	}

	private void addLine(String label, int value)
	{
		addLine(label, value, "");
	}

	private void addLine(String label, int value, String suffix)
	{
		// Degree units are only appended with labels; number-only mode contains
		// exactly the numeric value for a cleaner compact display.
		String valueText = value + (config.names() ? suffix : "");
		if (config.names())
		{
			panelComponent.getChildren().add(new DisplayLineComponent(label + ": " + valueText));
			return;
		}

		panelComponent.getChildren().add(new DisplayLineComponent(valueText));
	}

	private int toYawDegrees(int cameraYaw)
	{
		// Convert RuneLite's circular angular units into conventional 0-359 degrees.
		return (int) Math.round(cameraYaw * 360.0 / FULL_TURN_UNITS) % 360;
	}

	private int toPitchDegrees(int cameraPitch)
	{
		// Convert the allowed camera pitch range into a clamped 0-90 degree value.
		int degrees = (int) Math.round((cameraPitch - MIN_CAMERA_PITCH) * 90.0
			/ (MAX_CAMERA_PITCH - MIN_CAMERA_PITCH));
		return Math.max(0, Math.min(90, degrees));
	}

	private static class DisplayLineComponent implements LayoutableRenderableEntity
	{
		// One component owns one rendered text line and its exact bounds.
		private final String text;
		private final Rectangle bounds = new Rectangle();
		private Point preferredLocation = new Point();

		private DisplayLineComponent(String text)
		{
			this.text = text;
		}

		@Override
		public Dimension render(Graphics2D graphics)
		{
			// Preserve the graphics state because RuneLite reuses this Graphics2D
			// object when it renders other overlays.
			Font previousFont = graphics.getFont();
			Color previousColor = graphics.getColor();
			graphics.setFont(DISPLAY_FONT);
			FontMetrics metrics = graphics.getFontMetrics();
			int height = metrics.getHeight() + LINE_PADDING_Y * 2;
			// Paint each word independently so its white background only covers the
			// pixels immediately around that word, not the whole panel width.
			String[] words = text.split(" ");
			int width = 0;
			for (String word : words)
			{
				width += metrics.stringWidth(word) + LINE_PADDING_X * 2;
			}
			width += WORD_GAP * (words.length - 1);

			int x = preferredLocation.x;
			for (String word : words)
			{
				int wordWidth = metrics.stringWidth(word) + LINE_PADDING_X * 2;
				graphics.setColor(Color.WHITE);
				graphics.fillRect(x, preferredLocation.y, wordWidth, height);
				graphics.setColor(Color.BLACK);
				graphics.drawString(word, x + LINE_PADDING_X,
					preferredLocation.y + LINE_PADDING_Y + metrics.getAscent());
				x += wordWidth + WORD_GAP;
			}

			graphics.setFont(previousFont);
			graphics.setColor(previousColor);
			bounds.setBounds(preferredLocation.x, preferredLocation.y, width, height);
			return new Dimension(width, height);
		}

		@Override
		public Rectangle getBounds()
		{
			return bounds;
		}

		@Override
		public void setPreferredLocation(Point location)
		{
			preferredLocation = location;
		}

		@Override
		public void setPreferredSize(Dimension size)
		{
			// The background is sized to this line's text, not the panel width.
		}
	}

	private static class ClickStatusComponent implements LayoutableRenderableEntity
	{
		// This component is a fixed-size status square placed after the text lines.
		private final boolean actionHover;
		private final Rectangle bounds = new Rectangle();
		private Point preferredLocation = new Point();

		private ClickStatusComponent(boolean actionHover)
		{
			this.actionHover = actionHover;
		}

		@Override
		public Dimension render(Graphics2D graphics)
		{
			// Red denotes an interaction action; yellow denotes a non-action click.
			graphics.setColor(actionHover ? Color.RED : Color.YELLOW);
			graphics.fillRect(preferredLocation.x, preferredLocation.y, CLICK_STATUS_SIZE, CLICK_STATUS_SIZE);
			bounds.setBounds(preferredLocation.x, preferredLocation.y, CLICK_STATUS_SIZE, CLICK_STATUS_SIZE);
			return new Dimension(CLICK_STATUS_SIZE, CLICK_STATUS_SIZE);
		}

		@Override
		public Rectangle getBounds()
		{
			return bounds;
		}

		@Override
		public void setPreferredLocation(Point location)
		{
			preferredLocation = location;
		}

		@Override
		public void setPreferredSize(Dimension size)
		{
			// The indicator has a fixed square size.
		}
	}
}

package com.locationinfo;

import com.google.inject.Provides;
import java.util.LinkedHashSet;
import java.util.Set;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.WidgetNode;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.widgets.WidgetModalMode;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

/**
 * Registers the overlay and records the menu action used by the player's most
 * recent click. This class intentionally does not change any game state: it
 * only observes RuneLite events and supplies data to the overlay.
 */
@PluginDescriptor(
	name = "Player and Camera Info - QOL",
	description = "Game-state inspection aid for gameplay understanding and plugin debugging"
)
public class LocationInfoPlugin extends Plugin
{
	// Previous versions stored the zoom toggle under this key. Keep it only to
	// migrate an existing user's saved preference to the correctly named key.
	private static final String LEGACY_CAMERA_Z_KEY = "cameraZ";
	private final Set<Integer> openModalInterfaceIds = new LinkedHashSet<>();

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	private volatile boolean running;

	@Inject
	private ConfigManager configManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private LocationInfoOverlay overlay;

	@Override
	protected void startUp()
	{
		// Perform configuration migration before the overlay first reads it.
		migrateCameraZoomConfig();
		running = true;
		clientThread.invoke(() ->
		{
			if (running)
			{
				refreshOpenModalInterfaces();
			}
		});
		overlayManager.add(overlay);
	}

	@Override
	protected void shutDown()
	{
		// The overlay manager owns rendering, so removing it stops all display work.
		overlayManager.remove(overlay);
		running = false;
		clientThread.invoke(() ->
		{
			openModalInterfaceIds.clear();
			overlay.setCurrentModalInterfaceId(0);
		});
	}

	@Subscribe
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		// MenuOptionClicked is emitted after RuneLite processes a user click. The
		// overlay retains this classification for the "last click" indicator.
		overlay.setLastClickWasRed(event.getMenuAction());
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		for (WidgetNode node : client.getComponentTable())
		{
			if (node.getId() == event.getGroupId() && isModal(node.getModalMode()))
			{
				openModalInterfaceIds.remove(event.getGroupId());
				openModalInterfaceIds.add(event.getGroupId());
				updateCurrentModalInterface();
				return;
			}
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.isUnload() && isModal(event.getModalMode()))
		{
			openModalInterfaceIds.remove(event.getGroupId());
			updateCurrentModalInterface();
		}
	}

	private void refreshOpenModalInterfaces()
	{
		openModalInterfaceIds.clear();
		for (WidgetNode node : client.getComponentTable())
		{
			if (isModal(node.getModalMode()))
			{
				openModalInterfaceIds.add(node.getId());
			}
		}
		updateCurrentModalInterface();
	}

	private void updateCurrentModalInterface()
	{
		int currentId = 0;
		for (int groupId : openModalInterfaceIds)
		{
			currentId = groupId;
		}
		overlay.setCurrentModalInterfaceId(currentId);
	}

	private static boolean isModal(int modalMode)
	{
		return modalMode != WidgetModalMode.NON_MODAL;
	}

	/**
	 * Moves the old zoom preference to its new key once. A separately saved new
	 * value takes precedence, so upgrading cannot overwrite a later choice.
	 */
	private void migrateCameraZoomConfig()
	{
		Boolean legacyValue = configManager.getConfiguration(LocationInfoConfig.GROUP, LEGACY_CAMERA_Z_KEY, Boolean.class);
		if (legacyValue == null)
		{
			return;
		}

		Boolean currentValue = configManager.getConfiguration(LocationInfoConfig.GROUP, LocationInfoConfig.CAMERA_ZOOM_KEY, Boolean.class);
		if (currentValue == null)
		{
			configManager.setConfiguration(LocationInfoConfig.GROUP, LocationInfoConfig.CAMERA_ZOOM_KEY, legacyValue);
		}
		configManager.unsetConfiguration(LocationInfoConfig.GROUP, LEGACY_CAMERA_Z_KEY);
	}

	@Provides
	LocationInfoConfig provideConfig(ConfigManager configManager)
	{
		// Guice uses this method to provide one typed view of this plugin's config.
		return configManager.getConfig(LocationInfoConfig.class);
	}
}
